export const SPLIT_BOX_HIDDEN_CONTENT: SzBrowserDiagnostic<{ readonly hidden: string }> = {"id":"split-box-hidden-content","args":{"hidden":{}},"text":"`splitBox` put `{hidden}` on the content node, so the frame keeps its background, border and size and stays visible.","help":"pass `{ outer: ['hidden'] }` if the whole box should disappear."};

/** `szv-config-invalid`: A part of an szv config that does not have the shape szv reads. */
export const SZV_CONFIG_INVALID: SzBrowserDiagnostic<{ readonly form: 'config' | 'base' | 'variants' | 'default-variants' | 'dimension' | 'variant-value'; readonly dimension?: string; readonly token?: string; readonly got: string }> = {"id":"szv-config-invalid","args":{"form":{},"dimension":{},"token":{},"got":{}},"text":{"config":"The `szv` config is not an object (got {got}), so `szv` returns an empty sz object.","base":"`base` in the `szv` config is not an sz object (got {got}), so `szv` ignores it.","variants":"`variants` in the `szv` config is not an object (got {got}), so `szv` returns only `base`.","default-variants":"`defaultVariants` in the `szv` config is not an object (got {got}), so no variant gets a default value.","dimension":"`variants.{dimension}` is not an object of values (got {got}), so it adds no classes.","variant-value":"`variants.{dimension}.{token}` is not an sz object (got {got}), so it is ignored."},"help":{"config":"pass an object such as `{ base: { … }, variants: { … } }`.","base":"make `base` an sz object, such as `{ p: 4 }`.","variants":"make `variants` an object of dimensions, such as `{ size: { sm: { p: 2 } } }`.","default-variants":"make `defaultVariants` an object of values, such as `{ size: 'sm' }`.","dimension":"make `variants.{dimension}` an object that maps each value to an sz object.","variant-value":"make it an sz object, such as `{ p: 4 }`, or `null` to add nothing."}};

/** `sz-object-depth`: An sz object at runtime nested deeper than the depth limit. */
export const SZ_OBJECT_DEPTH: SzBrowserDiagnostic<{ readonly form: 'value' | 'szv-config'; readonly maxDepth: number; readonly where?: string }> = {"id":"sz-object-depth","args":{"form":{},"maxDepth":{},"where":{}},"text":{"value":"This `sz` value nests deeper than {maxDepth} levels, so csszyx rejects it.","szv-config":"`{where}` in the `szv` config nests deeper than {maxDepth} levels, so `szv` rejects it at render."},"help":{"value":"check what reaches the `sz` prop; nesting this deep usually means untrusted or looping data.","szv-config":"flatten `{where}`; nesting this deep usually means the config was built from untrusted or looping data."}};

/** `szv-forbidden-key`: A key in an szv config that csszyx never reads, such as __proto__. */
export const SZV_FORBIDDEN_KEY: SzBrowserDiagnostic<{ readonly where: string; readonly key: string }> = {"id":"szv-forbidden-key","args":{"where":{},"key":{}},"text":"`{where}` in the `szv` config has the forbidden key `{key}`, so it is ignored.","help":"remove the key; csszyx never reads `__proto__`, `constructor` or `prototype`."};

/** `szv-unknown-variant`: A selection that names a variant the szv config does not declare. */
export const SZV_UNKNOWN_VARIANT: SzBrowserDiagnostic<{ readonly key: string }> = {"id":"szv-unknown-variant","args":{"key":{}},"text":"The `szv` selection names the variant `{key}`, which `variants` does not declare, so it is ignored.","help":"declare `variants.{key}`, or remove `{key}` from the selection."};

/** `szv-unknown-variant-value`: A selection that gives a variant a value it has no styles for. */
export const SZV_UNKNOWN_VARIANT_VALUE: SzBrowserDiagnostic<{ readonly key: string; readonly value: string; readonly allowed: readonly string[] }> = {"id":"szv-unknown-variant-value","args":{"key":{},"value":{},"allowed":{"joiner":", "}},"text":"The `szv` selection sets `{key}` to `{value}`, which `variants.{key}` does not define, so it adds no class.","help":"use one of: {allowed}, or add `{value}` to `variants.{key}`."};

/** `szv-object-as-string`: An sz object from szv() used as a class string, which renders "[object Object]". */
export const SZV_OBJECT_AS_STRING: SzBrowserDiagnostic<Record<never, never>> = {"id":"szv-object-as-string","args":{},"text":"An sz object from `szv()` was used as a class string, such as `className={someSzv({ … })}`, which renders `[object Object]` in a production build.","help":"pass it to an `sz` prop, or turn it into a class string with `szr(…)` first.","note":"a development build renders an empty string in its place."};

/** `dynamic-injection-growth`: A session in which dynamic() has injected so many classes the CSSOM keeps growing. */
export const DYNAMIC_INJECTION_GROWTH: SzBrowserDiagnostic<{ readonly count: number }> = {"id":"dynamic-injection-growth","args":{"count":{}},"text":"`dynamic()` has injected {count} or more unique classes this session, and injected CSS rules are never removed, so the CSSOM keeps growing and style recalculation slows.","help":"drive continuously changing values, such as a width that changes every animation frame, through a CSS variable instead."};

/** `dynamic-unsafe-arbitrary`: An arbitrary value dynamic() dropped because it could inject CSS. */
export const DYNAMIC_UNSAFE_ARBITRARY: SzBrowserDiagnostic<{ readonly utility: string }> = {"id":"dynamic-unsafe-arbitrary","args":{"utility":{}},"text":"The arbitrary value in `{utility}` could inject CSS, so `dynamic()` omits the class.","help":"keep untrusted data out of arbitrary values, or validate it before it reaches `dynamic()`.","note":"only the first dropped value of a session is reported."};

/** `dynamic-non-boolean`: A runtime value that is not a boolean on a key only a boolean can toggle. */
export const DYNAMIC_NON_BOOLEAN: SzBrowserDiagnostic<{ readonly key: string; readonly valueType: string }> = {"id":"dynamic-non-boolean","args":{"key":{},"valueType":{}},"text":"The runtime value of `{key}` has type `{valueType}`, and only a boolean toggles this class, so it is omitted.","help":"pass `true` or `false`; write other values as literals, or use `dynamic()` for a responsive object."};

/** `dynamic-unresolvable`: A runtime value of a type no CSS value can be resolved from. */
export const DYNAMIC_UNRESOLVABLE: SzBrowserDiagnostic<{ readonly key: string; readonly valueType: string }> = {"id":"dynamic-unresolvable","args":{"key":{},"valueType":{}},"text":"The runtime value of `{key}` has type `{valueType}`, which cannot be resolved to CSS, so the property is omitted.","help":"pass a number, a token or a CSS length; for a responsive object, use `dynamic()`."};

/** `dev-warnings-partial`: A development warning with no source location; csszyx check names the file and key. */
export const DEV_WARNINGS_PARTIAL: SzBrowserDiagnostic<Record<never, never>> = {"id":"dev-warnings-partial","args":{},"text":"The `sz` key warning above has no source location, so it does not name the file that triggered it.","help":"run `npx @csszyx/cli check` to list every file and key at once; set `CSSZYX_NO_PROJECT_SCAN_HINT=1` to hide this line."};

/** `diagnostics-capped`: More findings of one kind than a run lists; the rest are counted, not printed. */
export const DIAGNOSTICS_CAPPED: SzBrowserDiagnostic<{ readonly form: 'per-id' | 'dev-warnings' | 'unknown-keys'; readonly id?: string; readonly count?: number }> = {"id":"diagnostics-capped","args":{"form":{},"id":{},"count":{}},"text":{"dev-warnings":"This session has printed {count} distinct development warnings, so further ones are suppressed.","unknown-keys":"This process has reported {count} distinct unknown sz keys, so further ones are suppressed."},"help":{"per-id":"`csszyx check --rule {id}` lists every one.","dev-warnings":"look above for one warning repeating with different values; a className built from data is the usual cause.","unknown-keys":"look above for one key repeating with different names; sz keys built from data are the usual cause."}};

/** `sz-attribute-syntax`: An sz attribute string that does not parse. */
export const SZ_ATTRIBUTE_SYNTAX: SzBrowserDiagnostic<{ readonly input: string; readonly char: string; readonly index: number }> = {"id":"sz-attribute-syntax","args":{"input":{},"char":{},"index":{}},"text":"The `sz` attribute `{input}` has an unexpected `{char}` at offset {index}, so the element gets no classes from it.","help":"write it as an object literal with commas between keys, such as `sz=\"p: 4, w: '1/2'\"`; quote a value that holds `/` or `#`.","console":"error"};

/** `options-object-required`: An options argument that is not the one object the call takes. */
export const OPTIONS_OBJECT_REQUIRED: SzBrowserDiagnostic<{ readonly form: 'transform' | 'csszyx-turbopack' }> = {"id":"options-object-required","args":{"form":{}},"text":{"transform":"`transform` takes its options in one object, so a second argument that is not an object, or a third argument, is refused.","csszyx-turbopack":"`csszyxTurbopack` takes one object, with the config to extend under `turbopack`, so a second argument or an option it does not know is refused."},"help":{"transform":"pass the prefix and the mangle map as keys: `transform(sz, { prefix: 'hover:', mangleMap })`.","csszyx-turbopack":"write `csszyxTurbopack({ turbopack: <your config>, ...options })`; loader options go beside `turbopack`."}};

/** `lowering-not-loaded`: An sz object passed to a string helper before the lowering module is loaded. */
export const LOWERING_NOT_LOADED: SzBrowserDiagnostic<Record<never, never>> = {"id":"lowering-not-loaded","args":{},"text":"A string helper received an sz object, but the module that turns sz objects into class names is not loaded, so it cannot produce class names for it.","help":"add `import '@csszyx/runtime/lowering';` once at startup when the code runs outside the csszyx bundler plugin, such as in unit tests or scripts; the plugin loads it for files that can pass objects at runtime."};

/** `lite-sz-object`: An sz object passed to a lite-runtime helper, which cannot lower objects. */
export const LITE_SZ_OBJECT: SzBrowserDiagnostic<{ readonly fnName: string; readonly received: string }> = {"id":"lite-sz-object","args":{"fnName":{},"received":{}},"text":"`{fnName}()` takes class strings and received the plain object `{received}`, because the compiler could not resolve this `sz` prop at build time.","help":"write `sz={[cond ? varA : varB, { key: 'val' }]}`; a spread of a conditional, such as `sz={{ ...(cond ? varA : varB), key: 'val' }}`, is the usual cause.","note":"a production build skips this check: `_sz` returns the object, or `[object Object]` beside other classes, and `_szMerge` throws a `TypeError`."};

/** `split-box-sz-string`: A class string passed to splitBoxSz, which takes sz objects. */
export const SPLIT_BOX_SZ_STRING: SzBrowserDiagnostic<{ readonly value: string }> = {"id":"split-box-sz-string","args":{"value":{}},"text":"`splitBoxSz` partitions sz objects, not class strings, so it cannot split `{value}`.","help":"use `splitBox()` for a class string.","note":"a production build drops the string instead of throwing."};

/** `runtime-prefix-conflict`: Two builds sharing one runtime that registered different Tailwind prefixes. */
export const RUNTIME_PREFIX_CONFLICT: SzBrowserDiagnostic<{ readonly form: 'prefixes' | 'unprefixed'; readonly first: string; readonly second?: string }> = {"id":"runtime-prefix-conflict","args":{"form":{},"first":{},"second":{}},"text":{"prefixes":"Two builds sharing one JavaScript runtime registered the Tailwind prefixes `{first}` and `{second}`, so csszyx cannot tell which prefix their classes take.","unprefixed":"Two builds sharing one JavaScript runtime registered different Tailwind prefixes, `{first}` and none, so csszyx cannot tell which prefix their classes take."},"help":"keep independently configured applications on separate `@csszyx/runtime` instances, or align their Tailwind prefix."};

/** `dynamic-manifest-unreachable`: A dynamic manifest the browser could not fetch. */
export const DYNAMIC_MANIFEST_UNREACHABLE: SzBrowserDiagnostic<{ readonly status: number }> = {"id":"dynamic-manifest-unreachable","args":{"status":{}},"text":"The `dynamic()` manifest could not be fetched (HTTP status {status}), so every class is treated as new and injected at runtime.","help":"serve the manifest at the URL `setManifestUrl` names, or turn `build.emitManifest` on.","note":"the error is caught and nothing is printed; csszyx does not fetch it again this session until you call `resetManifest`."};

/** `config-invalid`: A csszyx.config with problems, each reported with its own code. */
export const CONFIG_INVALID: SzBrowserDiagnostic<{ readonly form: 'partly-applied' | 'not-applied'; readonly count: number }> = {"id":"config-invalid","args":{"form":{},"count":{}},"text":{"partly-applied":"This file has {count} problem(s); each one is ignored, and the rest of the file applies.","not-applied":"This file has {count} problem(s), and it is not applied, so every finding keeps its default level."},"help":"https://csszyx.com/docs/reference/config/#csszyxconfig describes every field; a dev server, a watch build and `csszyx next watch` read it again when it or a module it imports is saved."};

/** `config-id-not-settable`: A rule id for a runtime line or a throw, whose level csszyx.config cannot set. */
export const CONFIG_ID_NOT_SETTABLE: SzBrowserDiagnostic<{ readonly id: string }> = {"id":"config-id-not-settable","args":{"id":{}},"text":"`{id}` is printed to the console or thrown, so `csszyx.config` sets no level for it.","help":"remove it; `rules` sets the level of engine diagnostics and `csszyx check` findings only."};

/** `removed-rule-id`: A rule id csszyx no longer reports, with the id that replaced it. */
export const REMOVED_RULE_ID: SzBrowserDiagnostic<{ readonly form: 'replaced' | 'removed'; readonly id: string; readonly replacedBy?: string }> = {"id":"removed-rule-id","args":{"form":{},"id":{},"replacedBy":{}},"text":"`{id}` is no longer reported, so a level or a selection naming it applies to nothing.","help":{"replaced":"name `{replacedBy}` instead, which reports what `{id}` did.","removed":"remove it."}};

/** `diagnostics-held`: Findings at info a production build counted instead of listing. */
export const DIAGNOSTICS_HELD: SzBrowserDiagnostic<{ readonly count: number }> = {"id":"diagnostics-held","args":{"count":{}},"text":"This build held back {count} finding(s) at `info` and listed none of them.","help":"run a development build to see each one with its file and position.","note":"they are the advisories csszyx handled — a fallback at an sz prop, a className whose precedence over sz is unstated, or a variable hoist the planner declined — and any finding `csszyx.config` sets to `info`."};
